/**
 * Demo corpus.
 *
 * These profiles are written directly rather than generated by running real
 * interviews, so `npm run db:seed` works with no API key and costs nothing. The
 * shape matches exactly what the finish route produces, so manager search, the
 * candidate list, and the candidate report render the same way they will with
 * real data.
 *
 * Two things are deliberately *not* hardcoded:
 *   - competency keys are validated against the real criteria files, so a seed
 *     that drifts from the standard fails loudly instead of producing candidates
 *     scored against competencies that no longer exist;
 *   - overall scores are computed by the real scoring function, so the seed
 *     cannot show a number the app's own rule would not produce.
 *
 * Every person here is invented.
 */

import { PrismaClient } from "@prisma/client";
import { embed } from "../src/lib/embeddings";
import { resolveCriteria } from "../src/lib/criteria/load";
import { computeOverall, type ScoredCompetency } from "../src/lib/assess/scoring";

const db = new PrismaClient();

type SeedScore = {
  key: string;
  score: number; // 0-10
  confidence: "low" | "medium" | "high";
  reached?: boolean;
  evidence: string;
  note: string;
};

type Seed = {
  name: string;
  email: string;
  phone: string;
  location: string;
  headline: string;
  roleSlug: string;
  seniority: string;
  years: number;
  recommendation: string;
  summary: string;
  scores: SeedScore[];
  strengths: string[];
  concerns: string[];
  tags: { label: string; kind: string; confidence: number; status: string; evidence: string }[];
};

