const SEED_INTEGRITY = JSON.stringify({
  anomalyScore: 0,
  band: "nothing_notable",
  observations: [],
  counts: {},
  caveat:
    "These are behavioural observations, not proof. Seed data — no real session was monitored.",
});

async function main() {
  console.log("Seeding demo candidates…");

  // Load every criteria file the seed references. This also creates the
  // CriteriaSet rows, so a fresh database has the standard in it before any
  // candidate is attached to one.
  const slugs = [...new Set(SEEDS.map((s) => s.roleSlug))];
  const criteriaBySlug = new Map(
    await Promise.all(
      slugs.map(async (slug) => [slug, await resolveCriteria(slug)] as const),
    ),
  );

  for (const s of SEEDS) {
    const criteria = criteriaBySlug.get(s.roleSlug);
    if (!criteria) throw new Error(`No criteria for ${s.roleSlug}`);

    // Seed scores are matched against the real criteria file rather than trusted.
    // If someone edits a criteria file and forgets the seed, this is where they
    // find out — rather than in a candidate report with blank axes.
    const byKey = new Map(s.scores.map((x) => [x.key, x]));
    const unknown = s.scores.filter((x) => !criteria.competencies.some((c) => c.key === x.key));
    if (unknown.length) {
      throw new Error(
        `${s.name}: scores reference competencies that criteria/${s.roleSlug}.md does not define: `
        + `${unknown.map((u) => u.key).join(", ")}`,
      );
    }

    const scored: ScoredCompetency[] = criteria.competencies.map((c) => {
      const x = byKey.get(c.key);
      return {
        competencyKey: c.key,
        label: c.label,
        score: x?.score ?? 0,
        priority: c.priority,
        confidence: x?.confidence ?? "low",
        evidenceQuote: x?.evidence ?? "",
        note: x?.note ?? "This competency was not covered by the interview.",
        source: "interview" as const,
        reached: x ? x.reached !== false : false,
      };
    });

    // The same function the app uses, so the seed cannot display a number the
    // real scoring rule would not produce.
    const overall = computeOverall(scored);

    const competenciesJson = JSON.stringify(
      scored.map((x) => ({
        competencyId: x.competencyKey,
        label: x.label,
        score: x.score,
        priority: x.priority,
        confidence: x.confidence,
        reached: x.reached,
        evidence: x.evidenceQuote,
        note: x.note,
        source: x.source,
      })),
    );

    const candidate = await db.candidate.upsert({
      where: { email: s.email },
      create: {
        email: s.email,
        name: s.name,
        phone: s.phone,
        location: s.location,
        consentInterview: true,
        consentRecording: true,
        consentLinkCheck: false,
        // So the cross-role compare control is exercisable straight after a seed.
        consentCrossRole: true,
        consentedAt: new Date(),
        consentPolicyVer: "2026-08-23",
      },
      update: {
        name: s.name, phone: s.phone, location: s.location, consentCrossRole: true,
      },
    });

    const searchText = [
      s.headline,
      `${s.seniority} ${criteria.roleTitle}`,
      criteria.sector,
      s.summary,
      s.tags
        .flatMap((t) =>
          Array.from(
            { length: t.status === "demonstrated" ? Math.max(1, Math.ceil(t.confidence * 3)) : 1 },
            () => t.label,
          ),
        )
        .join(" "),
      scored.filter((x) => x.reached).map((x) => `${x.label} ${x.note}`).join(" "),
    ].join("\n");

    const embedding = await embed(searchText);

    const profileFields = {
      headline: s.headline,
      sector: criteria.sector,
      roleSlug: criteria.roleSlug,
      roleTitle: criteria.roleTitle,
      seniority: s.seniority,
      yearsExperience: s.years,
      overallScore: overall.overall,
      recommendation: s.recommendation,
      summary: s.summary,
      searchText,
      embedding: JSON.stringify(embedding),
      competencies: competenciesJson,
    };

    await db.candidateProfile.upsert({
      where: { candidateId: candidate.id },
      create: { candidateId: candidate.id, ...profileFields },
      update: profileFields,
    });

    for (const t of s.tags) {
      const tag = await db.tag.upsert({
        where: { label: t.label },
        create: { label: t.label, kind: t.kind },
        update: {},
      });
      await db.candidateTag.upsert({
        where: { candidateId_tagId: { candidateId: candidate.id, tagId: tag.id } },
        create: {
          candidateId: candidate.id,
          tagId: tag.id,
          confidence: t.confidence,
          status: t.status,
          evidence: t.evidence || null,
        },
        update: { confidence: t.confidence, status: t.status },
      });
    }

    // Re-running the seed must not stack up duplicate interviews for the same
    // invented person.
    await db.interview.deleteMany({ where: { candidateId: candidate.id } });
    await db.resume.deleteMany({ where: { candidateId: candidate.id } });

    const resume = await db.resume.create({
      data: {
        candidateId: candidate.id,
        filename: "seed.txt",
        mimeType: "text/plain",
        rawText: `${s.name}\n${s.headline}\n(seed data)`,
        extracted: JSON.stringify({
          name: s.name, headline: s.headline, totalYearsExperience: s.years,
          employment: [], education: [], skills: [], notableClaims: [], links: [],
          email: s.email, phone: s.phone, location: s.location, summary: s.summary,
          sector: criteria.sector, seniority: s.seniority, gapsOrOddities: [],
        }),
      },
    });

    // Backdated, and deliberately so. startedAt defaults to now(), and the daily
    // spend cap in src/lib/gate.ts counts interviews started since midnight UTC
    // — so demo rows created at deploy time would eat a real candidate's slot,
    // and every redeploy would eat six more. Dated a week back, they never
    // collide with a live cap.
    const seededAt = new Date(Date.now() - 7 * 24 * 3600 * 1000);

    const interview = await db.interview.create({
      data: {
        candidateId: candidate.id,
        resumeId: resume.id,
        criteriaSetId: criteria.criteriaSetId,
        roleSlug: criteria.roleSlug,
        sector: criteria.sector,
        roleTitle: criteria.roleTitle,
        seniority: s.seniority,
        status: "completed",
        startedAt: seededAt,
        completedAt: seededAt,
        plan: JSON.stringify({
          criteria: {
            criteriaSetId: criteria.criteriaSetId,
            roleSlug: criteria.roleSlug,
            roleTitle: criteria.roleTitle,
            sector: criteria.sector,
            version: criteria.version,
            sourcePath: criteria.sourcePath,
            sourceHash: criteria.sourceHash,
            competencies: criteria.competencies.map((c) => ({
              id: c.key,
              label: c.label,
              description: c.description,
              probes: c.strongAnswer,
              weakSignals: c.weakAnswer,
              priority: c.priority,
            })),
          },
          sector: criteria.sector,
          roleTitle: criteria.roleTitle,
          seniority: s.seniority,
          questionBudget: 12,
          targets: criteria.competencies.map((c) => ({
            competencyId: c.key,
            label: c.label,
            targetQuestions: c.priority === "high" ? 2 : 1,
          })),
          resumeProbes: [],
          openingQuestion: "(seed data — no interview was conducted)",
          focusRationale: "Seed data.",
          createdAt: new Date().toISOString(),
        }),
      },
    });

    await db.assessment.create({
      data: {
        interviewId: interview.id,
        criteriaSetId: criteria.criteriaSetId,
        overallScore: overall.overall,
        recommendation: s.recommendation,
        summary: s.summary,
        competenciesCounted: overall.counted,
        competenciesTotal: overall.total,
        competencies: competenciesJson,
        strengths: JSON.stringify(s.strengths),
        concerns: JSON.stringify(s.concerns),
        integrity: SEED_INTEGRITY,
        resumeDeltas: JSON.stringify([]),
        scores: {
          create: scored.map((x) => ({
            competencyKey: x.competencyKey,
            label: x.label,
            score: x.score,
            confidence: x.confidence,
            evidenceQuote: x.evidenceQuote,
            note: x.note,
            source: x.source,
            reached: x.reached,
          })),
        },
      },
    });

    console.log(
      `  ${s.name.padEnd(18)} ${criteria.roleTitle.padEnd(28)} `
      + `${String(overall.overall).padStart(3)}/100  (${overall.counted}/${overall.total} competencies)`,
    );
  }

  console.log(`\nDone. ${SEEDS.length} candidates across ${slugs.length} roles.`);
  console.log('Try the manager search with: "Software engineer who has experience with PyTorch"');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => db.$disconnect());
